namespace sv_8de8e4dba7e14e1aa5f1bf35bc92cf03.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_8de8e4dba7e14e1aa5f1bf35bc92cf03.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">×</button>
            </div>
        }
    </main>
</div>

@* ===== PROFILE SECTION ===== *@
@{
    void ProfileSection()
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>
            <div class="profile-form">
                <div class="avatar-area">
                    <div class="avatar-preview">
                        @if (!string.IsNullOrEmpty(editProfile.AvatarUrl))
                        {
                            <img src="@editProfile.AvatarUrl" alt="Avatar" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">No Avatar</div>
                        }
                    </div>
                    <div class="avatar-url">
                        <label>Avatar URL</label>
                        <input type="url" @bind="editProfile.AvatarUrl" placeholder="https://example.com/avatar.png" />
                    </div>
                </div>

                <div class="form-group">
                    <label>Display Name</label>
                    <input type="text" @bind="editProfile.DisplayName" />
                </div>

                <div class="form-group">
                    <label>Email</label>
                    <input type="email" @bind="editProfile.Email" />
                </div>

                <div class="form-group">
                    <label>Bio</label>
                    <textarea rows="4" @bind="editProfile.Bio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </section>
    }
}

@* ===== NOTIFICATIONS SECTION ===== *@
@{
    void NotificationsSection()
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.PushNotifications" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>
            </div>

            <h3>Muted Channels</h3>
            <div class="channels-list">
                @if (availableChannels.Count > 0)
                {
                    @foreach (var channel in availableChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@editNotifications.MutedChannels.Contains(ch)"
                                   @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            @ch
                        </label>
                    }
                }
                else
                {
                    <p class="muted-text">No channels available.</p>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    }
}

@* ===== SECURITY SECTION ===== *@
@{
    void SecuritySection()
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="TogglePasswordPanel">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                </button>
                @if (showPasswordPanel)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(passwordError))
                        {
                            <div class="error-message">@passwordError</div>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="security-item">
                <div class="two-factor">
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(securitySettings?.TwoFactorEnabled == true ? "✓ Enabled" : "✗ Disabled")
                    </span>
                </div>
                @if (securitySettings?.LastPasswordChange.HasValue == true)
                {
                    <p class="muted-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions?.Count > 0)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != securitySettings.Sessions.First())
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="muted-text">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p class="muted-text">No active sessions.</p>
            }

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> in <strong>@sessionToRevoke?.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    }
}

@* ===== APPEARANCE SECTION ===== *@
@{
    void AppearanceSection()
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light"
                               checked="@(editAppearance.Theme == "Light")"
                               @onchange='() => editAppearance.Theme = "Light"' />
                        Light
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark"
                               checked="@(editAppearance.Theme == "Dark")"
                               @onchange='() => editAppearance.Theme = "Dark"' />
                        Dark
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System"
                               checked="@(editAppearance.Theme == "System")"
                               @onchange='() => editAppearance.Theme = "System"' />
                        System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small"
                               checked="@(editAppearance.FontSize == "Small")"
                               @onchange='() => editAppearance.FontSize = "Small"' />
                        Small
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium"
                               checked="@(editAppearance.FontSize == "Medium")"
                               @onchange='() => editAppearance.FontSize = "Medium"' />
                        Medium
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large"
                               checked="@(editAppearance.FontSize == "Large")"
                               @onchange='() => editAppearance.FontSize = "Large"' />
                        Large
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Language</label>
                <select @bind="editAppearance.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Card Title</strong>
                    <p>Card content with your chosen theme and font size.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    }
}

