                    <div class="avatar-preview">
                        @if (!string.IsNullOrEmpty(editProfile.AvatarUrl))
                        {
                            <img src="@editProfile.AvatarUrl" alt="Avatar" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">No Avatar</div>
                        }
                    </div>
                    <div class="avatar-url">
                        <label>Avatar URL</label>
                        <input type="url" @bind="editProfile.AvatarUrl" placeholder="https://example.com/avatar.png" />
                    </div>
                </div>

                <div class="form-group">
                    <label>Display Name</label>
                    <input type="text" @bind="editProfile.DisplayName" />
                </div>

                <div class="form-group">
                    <label>Email</label>
                    <input type="email" @bind="editProfile.Email" />
                </div>

                <div class="form-group">
                    <label>Bio</label>
                    <textarea rows="4" @bind="editProfile.Bio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </section>
    }
}

@* ===== NOTIFICATIONS SECTION ===== *@
@{
    void NotificationsSection()
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.PushNotifications" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>
            </div>

            <h3>Muted Channels</h3>
            <div class="channels-list">
                @if (availableChannels.Count > 0)
                {
                    @foreach (var channel in availableChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@editNotifications.MutedChannels.Contains(ch)"
                                   @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            @ch
                        </label>
                    }
                }
                else
                {
                    <p class="muted-text">No channels available.</p>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    }
}

@* ===== SECURITY SECTION ===== *@
@{
    void SecuritySection()
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="TogglePasswordPanel">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                </button>
                @if (showPasswordPanel)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(passwordError))
                        {
                            <div class="error-message">@passwordError</div>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="security-item">
                <div class="two-factor">
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(securitySettings?.TwoFactorEnabled == true ? "✓ Enabled" : "✗ Disabled")
                    </span>
                </div>
                @if (securitySettings?.LastPasswordChange.HasValue == true)
                {
                    <p class="muted-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            @if (securitySettings?.Sessions?.Count > 0)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != securitySettings.Sessions.First())
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="muted-text">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p class="muted-text">No active sessions.</p>
            }

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> in <strong>@sessionToRevoke?.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    }
}

@* ===== APPEARANCE SECTION ===== *@
@{
    void AppearanceSection()
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light"
                               checked="@(editAppearance.Theme == "Light")"
                               @onchange='() => editAppearance.Theme = "Light"' />
                        Light
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark"
                               checked="@(editAppearance.Theme == "Dark")"
                               @onchange='() => editAppearance.Theme = "Dark"' />
                        Dark
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System"
                               checked="@(editAppearance.Theme == "System")"
                               @onchange='() => editAppearance.Theme = "System"' />
                        System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small"
                               checked="@(editAppearance.FontSize == "Small")"
                               @onchange='() => editAppearance.FontSize = "Small"' />
                        Small
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium"
                               checked="@(editAppearance.FontSize == "Medium")"
                               @onchange='() => editAppearance.FontSize = "Medium"' />
                        Medium
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large"
                               checked="@(editAppearance.FontSize == "Large")"
                               @onchange='() => editAppearance.FontSize = "Large"' />
                        Large
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Language</label>
                <select @bind="editAppearance.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Card Title</strong>
                    <p>Card content with your chosen theme and font size.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    }
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string toastMessage = "";
    private string toastType = "";

    // Profile
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    editProfile = EditableProfile.FromModel(savedProfile);
                    break;
                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    editNotifications = EditableNotifications.FromModel(prefs);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    break;
                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    editAppearance = EditableAppearance.FromModel(appearance);
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading data: {ex.Message}", "error");
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            editProfile = EditableProfile.FromModel(savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        passwordError = "";
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New passwords do not match.";
            return;
        }
        if (newPassword.Length < 8)
        {
            passwordError = "Password must be at least 8 characters.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            showPasswordPanel = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
        showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        CancelRevoke();
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editAppearance.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => toastMessage = "";

    // Editable view models
    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static EditableProfile FromModel(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();

        public static EditableNotifications FromModel(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "System";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "en";
        public bool CompactMode { get; set; }

        public static EditableAppearance FromModel(AppearanceSettings s) => new()
        {
            Theme = s.Theme,
            FontSize = s.FontSize,
            Language = s.Language,
            CompactMode = s.CompactMode
        };
    }
}

arguments.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: #495057;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    color: #212529;
    font-size: 1.5rem;
    border-bottom: 1px solid #e0e0e0;
    padding-bottom: 0.75rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #495057;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #495057;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

/* Avatar */
.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
    flex-shrink: 0;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #6c757d;
    font-size: 0.8rem;
    text-align: center;
}

.avatar-url {
    flex: 1;
}

.avatar-url label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #495057;
    font-size: 0.9rem;
}

.avatar-url input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    margin-bottom: 0.5rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 40px;
    height: 22px;
    appearance: none;
    background: #ced4da;
    border-radius: 11px;
    position: relative;
    cursor: pointer;
    transition: background 0.3s;
    flex-shrink: 0;
}

.toggle-label input[type="checkbox"]::after {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 18px;
    height: 18px;
    background: white;
    border-radius: 50%;
    transition: transform 0.3s;
}

.toggle-label input[type="checkbox"]:checked {
    background: #0d6efd;
}

.toggle-label input[type="checkbox"]:checked::after {
    transform: translateX(18px);
}

/* Channels */
.channels-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #e9ecef;
}

/* Security - expandable panel */
.expandable-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.two-factor {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 500;
}

.status-indicator {
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 600;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #495057;
}

.sessions-table tr:hover {
    background: #f8f9fa;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e0e0e0;
